function describeViewport(win) {
  return { width: win.innerWidth, height: win.innerHeight };
}
console.log(describeViewport({ innerWidth: 800, innerHeight: 600 }));
// { width: 800, height: 600 }

function observeWidth(win, onWidth) {
  const update = () => onWidth(win.innerWidth);
  win.addEventListener("resize", update);
  update();
  return () => win.removeEventListener("resize", update);
}

async function readText(url) {
  const response = await fetch(url);
  if (!response.ok) throw new Error("HTTP " + response.status);
  return response.text();
}
// 浏览器中调用 readText("/notice.txt")，得到通知文本的 Promise。

async function getJson(url) {
  const response = await fetch(url);
  if (!response.ok) throw new Error("服务器返回 " + response.status);
  if (response.status === 204) return null;
  return response.json();
}

