function range(start, end) {
  if (!Number.isSafeInteger(start) || !Number.isSafeInteger(end)) throw new TypeError("需要安全整数");
  return { *[Symbol.iterator]() { for (let n = start; n < end; n++) yield n; } };
}
const values = range(2, 5);
console.log([...values]); // [2,3,4]
console.log([...values]); // [2,3,4]

