const yieldTask = () => new Promise(resolve => setTimeout(resolve, 0));
async function processInChunks(items, handle) {
  for (let i = 0; i < items.length; i++) {
    handle(items[i]);
    if ((i + 1) % 100 === 0) await yieldTask();
  }
}

